bool isPrime(int n)
{
    if (n < 2) return false;
    for (int d = 2; d * d <= n; d++)
        if (n % d == 0) return false;   // return сразу выходит из функции
    return true;
}
//---
for (int i = 1; i <= 20; i++) if (isPrime(i)) cout << i << " ";

void stats(const int a[], int n, int &mn, int &mx, double &avg)
{
    mn = mx = a[0];
    int s = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
        s += a[i];
    }
    avg = (double)s / n;
}
//---
int a[6] = {7, -2, 10, 4, 4, 1};
int lo, hi; double av;
stats(a, 6, lo, hi, av);
cout << lo << " " << hi << " " << av;

void fill(int a[], int n)               // меняет массив — без const
{
    for (int i = 0; i < n; i++) a[i] = (i * 7 + 3) % 10;   // вместо cin, для примера
}
void show(const int a[], int n)          // const: менять запрещено
{
    for (int i = 0; i < n; i++) cout << a[i] << " ";
    cout << endl;
}
int aboveAvg(const int a[], int n)
{
    double s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    double avg = s / n;
    int k = 0;
    for (int i = 0; i < n; i++) if (a[i] > avg) k++;
    return k;
}
//---
int a[8];
fill(a, 8);
show(a, 8);
cout << aboveAvg(a, 8);

long power(long x, int n)
{
    if (n == 0) return 1;
    long h = power(x, n / 2);
    return n % 2 == 0 ? h * h : h * h * x;
}
int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
void bin(int n)
{
    if (n > 1) bin(n / 2);       // сначала старшие разряды
    cout << n % 2;
}
//---
