char shift(char c, int k)
{
    if (c >= 'a' && c <= 'z') return 'a' + (c - 'a' + k) % 26;
    if (c >= 'A' && c <= 'Z') return 'A' + (c - 'A' + k) % 26;
    return c;
}
int main()
{
    char a[] = "Hello World";
    for (int i = 0; a[i]; i++) a[i] = shift(a[i], 3);
    string s = "Hello World";
    for (int i = 0; i < (int)s.length(); i++) s[i] = shift(s[i], 3);
    cout << a << endl << s << endl << (s == a ? "same" : "diff");
