class Time {
    int h, m;
public:
    void set(int hh, int mm)
    {
        h = (hh >= 0 && hh < 24) ? hh : 0;
        m = (mm >= 0 && mm < 60) ? mm : 0;
    }
    void addMinutes(int k)
    {
        int t = (h * 60 + m + k) % (24 * 60);
        h = t / 60; m = t % 60;
    }
    void print() const
    {
        if (h < 10) cout << 0;
        cout << h << ":";
        if (m < 10) cout << 0;
        cout << m << endl;
    }
};
