t.print();
t.addMinutes(90);
t.print();

class Account {
    int number;
    double balance;
    static int created;
public:
    Account() { number = ++created; balance = 0; }
    void deposit(double s) { if (s > 0) balance += s; }
    bool withdraw(double s)
    {
        if (s <= 0 || s > balance) return false;
        balance -= s;
        return true;
    }
    bool transfer(Account &to, double s)
    {
        if (!withdraw(s)) return false;
        to.deposit(s);
        return true;
    }
    void print() const { cout << "#" << number << ": " << balance << endl; }
    static int count() { return created; }
};
int Account::created = 0;
