#include <iostream>
#include <string>
using namespace std;

class Book {
private:
    string title;
    string author;
    int publicationYear;
    string isbn;
    bool isAvailable;
public:
    Book() : title("Unknown"), author("Unknown"), publicationYear(0), isbn("Unknown"), isAvailable(true) { }
    Book(string t, string a, int y, string i)
        : title(t), author(a), publicationYear(0), isbn(i), isAvailable(true)
    {
        setPublicationYear(y);              // переиспользуем проверку
    }
    // Геттеры — const: не меняют объект
    string getTitle() const { return title; }
    string getAuthor() const { return author; }
    int getPublicationYear() const { return publicationYear; }
    string getISBN() const { return isbn; }
    bool getAvailability() const { return isAvailable; }
    // Сеттеры с проверкой
    void setPublicationYear(int year)
    {
        const int CURRENT_YEAR = 2026;
        if (year >= 1000 && year <= CURRENT_YEAR) publicationYear = year;
        else cout << "Error: invalid year " << year << endl;
    }
    void setIsbn(const string &newIsbn) { isbn = newIsbn; }
    // Остальные методы
    void displayBookInfo() const
    {
        cout << "'" << title << "' by " << author << ", " << publicationYear
             << ", ISBN " << isbn << " - " << (isAvailable ? "Available" : "Checked Out") << endl;
    }
    void checkOut()
    {
        if (isAvailable) { isAvailable = false; cout << title << " has been successfully checked out." << endl; }
        else cout << title << " is currently unavailable." << endl;
    }
    void returnBook()
    {
        if (!isAvailable) { isAvailable = true; cout << title << " has been successfully returned." << endl; }
        else cout << title << " is already in the library." << endl;
    }
};

int main()
{
    Book b1;                                                        // по умолчанию
    Book b2("Abai Zholy", "M. Auezov", 1942, "978-601-1");          // с параметрами
    Book b3("Clean Code", "R. Martin", 3000, "978-013-2");          // неверный год
    b1.displayBookInfo();
    b2.displayBookInfo();
    b3.displayBookInfo();
    b2.checkOut();
    b2.checkOut();                  // повторно — недоступна
    b2.returnBook();
    b2.returnBook();                // уже в библиотеке
    b3.setPublicationYear(2008);
    b3.setIsbn("978-0132350884");
    b3.displayBookInfo();
    cout << "Getter: " << b2.getTitle() << " / " << b2.getAuthor() << endl;
    return 0;
}

