class Stack {
    int *buf;
    int cap, top;
public:
    Stack(int c) : cap(c), top(0) { buf = new int[cap]; }
    ~Stack() { delete [] buf; }
    bool push(int v) { if (top == cap) return false; buf[top++] = v; return true; }
    int pop() { return buf[--top]; }
    bool isEmpty() const { return top == 0; }
};
