class Date {
    int d, m, y;
    static bool leap(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
    static int daysIn(int m, int y)
    {
        int t[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        return (m == 2 && leap(y)) ? 29 : t[m - 1];
    }
public:
    Date() : d(1), m(1), y(2000) { }
    bool set(int dd, int mm, int yy)
    {
        if (yy < 1 || mm < 1 || mm > 12 || dd < 1 || dd > daysIn(mm, yy)) return false;
        d = dd; m = mm; y = yy;
        return true;
    }
    void next()
    {
        if (++d > daysIn(m, y)) { d = 1; if (++m > 12) { m = 1; y++; } }
    }
    void print() const { cout << d << "." << m << "." << y << " "; }
};
