class Matrix {
    int n;
    int *a;
public:
    Matrix(int size) : n(size)
    {
        a = new int[n * n];
        for (int i = 0; i < n * n; i++) a[i] = (i / n == i % n) ? 1 : 0;
    }
    Matrix(const Matrix &o) : n(o.n)
    {
        a = new int[n * n];
        for (int i = 0; i < n * n; i++) a[i] = o.a[i];
    }
    ~Matrix() { delete [] a; }
    void set(int i, int j, int v) { a[i * n + j] = v; }
    int get(int i, int j) const { return a[i * n + j]; }
    Matrix multiply(const Matrix &b) const
    {
        Matrix r(n);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int s = 0;
                for (int k = 0; k < n; k++) s += get(i, k) * b.get(k, j);
                r.set(i, j, s);
            }
        return r;
    }
    int trace() const { int s = 0; for (int i = 0; i < n; i++) s += get(i, i); return s; }
};
//---
Matrix A(2);
A.set(0, 0, 1); A.set(0, 1, 2); A.set(1, 0, 3); A.set(1, 1, 4);
Matrix B = A;               // копия
B.set(0, 0, 10);            // A не меняется
Matrix C = A.multiply(A);   // A²
cout << A.trace() << " " << B.trace() << " " << C.get(0, 0) << " " << C.get(1, 1) << " " << C.trace();

